in_paths=[f'/root/paper{i}.pdf' for i in range(1,4)]
out_dir='/root/redacted'
os.makedirs(out_dir, exist_ok=True)

# Patterns to find in text (regex) and also simple strings for search_for
regex_patterns=[
    r'[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}',
    r'arXiv\s*:\s*\d{4}\.\d{4,5}(v\d+)?',
    r'arxiv\.org/abs/\d{4}\.\d{4,5}(v\d+)?',
    r'arXiv\s+preprint\s+arXiv\s*:\s*\d{4}\.\d{4,5}(v\d+)?',
]
string_patterns=[
    'arXiv', 'arxiv.org',
    'Accepted to', 'accepted to', 'Accepted at', 'accepted at',
    'To appear in', 'to appear in',
    'camera-ready', 'Camera-ready',
    'Proceedings of',
    'Correspondence',
    'Equal contribution', 'Equal Contribution',
    'Acknowledgments', 'Acknowledgements'
]

stop_tokens={
    'Preprint','Abstract','ABSTRACT','Introduction','Index','Terms','Index Terms',
    'University','Institute','Laboratory','Lab','College','Department','School','Inc','LLC','Ltd',
    'Correspondence','Proceedings','of','and','the','a','an','for','with','to','in','on','at',
    'USA','China','Canada','UK','U.S.','U.S','US'
}

def get_author_tokens(page, abstract_y0):
    # Extract words between top and abstract to find names
    words=page.get_text('words')  # list of (x0,y0,x1,y1,word,block_no,line_no,word_no)
    tokens=set()
    for x0,y0,x1,y1,w,_,_,_ in words:
        if y1 <= abstract_y0 - 1:
            # likely in title/author block area
            # skip pure symbols
            if not re.search(r'[A-Za-z]', w):
                continue
            # strip punctuation
            w_clean=re.sub(r"[^A-Za-z\-']","",w)
            if not w_clean:
                continue
            if w_clean in stop_tokens:
                continue
            if w_clean[0].isupper() and (len(w_clean) > 2):
                tokens.add(w_clean)
    return tokens

for path in in_paths:
    doc=fitz.open(path)
    page0=doc[0]
    # Find abstract block
    abstract_rect=None
    for inst in page0.search_for('Abstract') + page0.search_for('ABSTRACT'):
        abstract_rect=inst
        break
    if abstract_rect is None:
        # fallback: find line containing 'Abstract' in text
        text=page0.get_text('text')
        if 'abstract' in text.lower():
            # pick first block containing 'abstract'
            for b in page0.get_text('blocks'):
                if 'abstract' in b[4].lower():
                    abstract_rect=fitz.Rect(b[:4])
                    break
    # Find title rect via max font size
    title_rect=None
    spans=[]
    for b in page0.get_text('dict')['blocks']:
        if b['type'] != 0:
            continue
        for line in b['lines']:
            for span in line['spans']:
                spans.append(span)
    if spans:
        max_size=max(s['size'] for s in spans)
        # allow small tolerance
        title_spans=[s for s in spans if s['size'] >= max_size - 0.5]
        if title_spans:
            r=fitz.Rect(title_spans[0]['bbox'])
            for s in title_spans[1:]:
                r |= fitz.Rect(s['bbox'])
            title_rect=r

    # Compute author-block redaction area
    if abstract_rect and title_rect:
        y0=title_rect.y1 + 1
        y1=abstract_rect.y0 - 1
        if y1 > y0:
            page0.add_redact_annot(fitz.Rect(0, y0, page0.rect.width, y1), fill=(0,0,0))

    # Collect author tokens for header/footer redaction on all pages
    author_tokens=set()
    if abstract_rect:
        author_tokens=get_author_tokens(page0, abstract_rect.y0)

    # Build list of exact strings to search using regex patterns
    for page in doc:
        page_h=page.rect.height
        # regex matches from full text
        text=page.get_text('text')
        matches=set()
        for pat in regex_patterns:
            for m in re.findall(pat, text):
                if isinstance(m, tuple):
                    m=''.join(m)
                matches.add(m)
        # exact search for regex matches
        for m in matches:
            if not m:
                continue
            for inst in page.search_for(m):
                # redact just the line region around the match
                rect=fitz.Rect(inst.x0-1, inst.y0-1, inst.x1+1, inst.y1+1)
                page.add_redact_annot(rect, fill=(0,0,0))

        # simple string patterns
        for sp in string_patterns:
            for inst in page.search_for(sp):
                # For Proceedings of, only redact if header/footer
                if sp == 'Proceedings of':
                    if inst.y0 > 80 and inst.y1 < page_h - 80:
                        continue
                # Acknowledgments: redact from its line to end of page (conservative)
                if sp in ('Acknowledgments','Acknowledgements'):
                    rect=fitz.Rect(0, inst.y0-2, page.rect.width, page.rect.height)
                    page.add_redact_annot(rect, fill=(0,0,0))
                    continue
                rect=fitz.Rect(inst.x0-1, inst.y0-1, inst.x1+1, inst.y1+1)
                page.add_redact_annot(rect, fill=(0,0,0))

        # redact author tokens in header/footer
        if author_tokens:
            for tok in author_tokens:
                for inst in page.search_for(tok):
                    if inst.y0 <= 70 or inst.y1 >= page_h - 70:
                        rect=fitz.Rect(inst.x0-1, inst.y0-1, inst.x1+1, inst.y1+1)
                        page.add_redact_annot(rect, fill=(0,0,0))

    # apply redactions
    for page in doc:
        if page.has_redactions():
            page.apply_redactions(images=fitz.PDF_REDACT_IMAGE_NONE)

    out_path=os.path.join(out_dir, os.path.basename(path))
    doc.save(out_path)
    doc.close()

print('done')
